/// `String.valueOf(double)`.
// PORT: Java's Double.toString (shortest repr, "1.0E10" form) — a shared java::lang helper should replace this
fn java_double_to_string(d: f64) -> String {
    if d.is_nan() {
        return "NaN".to_string();
    }
    if d.is_infinite() {
        return if d > 0.0 {
            "Infinity".to_string()
        } else {
            "-Infinity".to_string()
        };
    }
    let abs = d.abs();
    if abs != 0.0 && !(1e-3..1e7).contains(&abs) {
        let s = format!("{:e}", d);
        let (mantissa, exp) = s.split_once('e').unwrap();
        let mantissa = if mantissa.contains('.') {
            mantissa.to_string()
        } else {
            format!("{}.0", mantissa)
        };
        return format!("{}E{}", mantissa, exp);
    }
    let s = format!("{}", d);
    if s.contains('.') {
        s
    } else {
        format!("{}.0", s)
    }
}
